(() => {
'use strict';
const $ = (s,el=document)=>el.querySelector(s);
const $$ = (s,el=document)=>[...el.querySelectorAll(s)];
let lang='en';try{lang=localStorage.getItem('770-language')==='he'?'he':'en'}catch{}
const t=(en,he)=>lang==='he'?he:en;
const state={type:'',stage:'',budget:'',timeline:'',idea:'',name:'',email:''};
let step=0,opener=null;
const form=$('#brief-form');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function language(){document.documentElement.lang=lang;document.documentElement.dir=lang==='he'?'rtl':'ltr';$$('[data-en]').forEach(el=>el.textContent=el.dataset[lang]);$('#language').textContent=lang==='en'?'HE':'EN';$('#language').setAttribute('aria-label',t('Switch to Hebrew','Switch to English'));document.title=t('770labs — From what if. To what’s next.','770labs — מרעיון נועז. לדבר הבא.');$$('[data-close]').forEach(el=>el.setAttribute('aria-label',t('Close dialog','סגירת חלון')));$('.menu-toggle').setAttribute('aria-label',t('Toggle navigation','פתיחה וסגירת ניווט'));$('.next-project .round-button').setAttribute('aria-label',t('Start a project','מתחילים פרויקט'));$('.project-visual').setAttribute('aria-label',t('Visit Chabad Calendar (opens in a new tab)','לפתיחת לוח חב״ד בלשונית חדשה'));$$('img[src="assets/chabad-calendar.png"]').forEach(el=>el.alt=t('Chabad Calendar interface showing the Hebrew calendar and daily events','ממשק לוח חב״ד עם לוח עברי ואירועי היום'));if($('#project-dialog').open)renderStep()}
$('#language').addEventListener('click',()=>{lang=lang==='en'?'he':'en';try{localStorage.setItem('770-language',lang)}catch{}language()});
language();$('#year').textContent=new Date().getFullYear();
$('.menu-toggle').addEventListener('click',()=>{const nav=$('.mobile-nav');nav.hidden=!nav.hidden;$('.menu-toggle').setAttribute('aria-expanded',String(!nav.hidden))});$$('.mobile-nav a').forEach(a=>a.addEventListener('click',()=>{$('.mobile-nav').hidden=true;$('.menu-toggle').setAttribute('aria-expanded','false')}));
function openDialog(id,el){opener=el;$(id).showModal();document.body.classList.add('dialog-open')}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{document.body.classList.remove('dialog-open');opener?.focus()});$('[data-close]',d).addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
$$('[data-start]').forEach(b=>b.addEventListener('click',()=>{step=0;renderStep();openDialog('#project-dialog',b)}));
$('#case-open').addEventListener('click',e=>openDialog('#case-dialog',e.currentTarget));$('#privacy-open').addEventListener('click',e=>openDialog('#privacy-dialog',e.currentTarget));
const choices={type:[['website','Website','אתר'],['app','Application','אפליקציה'],['redesign','Redesign','עיצוב מחדש'],['explore','Let’s explore','נחשוב יחד']],stage:[['idea','An early idea','רעיון ראשוני'],['plan','A defined plan','תוכנית מגובשת'],['existing','An existing product','מוצר קיים']],budget:[['discuss','Let’s discuss','נדבר על זה'],['under10','Under ₪10,000','עד 10,000 ₪'],['10to30','₪10,000–30,000','10,000–30,000 ₪'],['30to70','₪30,000–70,000','30,000–70,000 ₪'],['70plus','₪70,000+','מעל 70,000 ₪']],timeline:[['flexible','Flexible','גמיש'],['soon','As soon as possible','בהקדם האפשרי'],['1to3','In 1–3 months','בעוד 1–3 חודשים'],['3plus','In 3+ months','בעוד 3 חודשים ומעלה']]};
const label=(key)=>{const v=choices[key]?.find(c=>c[0]===state[key]);return v?t(v[1],v[2]):t('Not specified','לא צוין')};
function radios(key){return '<div class="choice-grid">'+choices[key].map(c=>`<label class="choice"><input type="radio" name="${key}" value="${c[0]}" ${state[key]===c[0]?'checked':''}>${escape(t(c[1],c[2]))}</label>`).join('')+'</div>'}
function select(key,title){return `<label class="field">${title}<select name="${key}">${choices[key].map(c=>`<option value="${c[0]}" ${state[key]===c[0]?'selected':''}>${escape(t(c[1],c[2]))}</option>`).join('')}</select></label>`}
function brief(){return t('New project enquiry — 770labs','פנייה לפרויקט חדש — 770labs')+'\n\n'+t('Name: ','שם: ')+state.name+'\n'+t('Email: ','אימייל: ')+state.email+'\n'+t('Project: ','פרויקט: ')+label('type')+'\n'+t('Stage: ','שלב: ')+label('stage')+'\n'+t('Budget: ','תקציב: ')+label('budget')+'\n'+t('Timeline: ','לוח זמנים: ')+label('timeline')+'\n\n'+state.idea}
function renderStep(){const title=[t('What are we building?','מה בונים יחד?'),t('Tell us a little more.','ספרו לנו קצת יותר.'),t('Who’s behind the idea?','מי מאחורי הרעיון?'),t('Your next chapter starts here.','הפרק הבא שלכם מתחיל כאן.')];$('#step-label').textContent=t(`STEP 0${step+1} / 04`,`שלב 0${step+1} / 04`);$('#step-bar').style.width=((step+1)*25)+'%';$('#back-step').textContent=t('← Back','חזרה →');$('#back-step').hidden=step===0;$('#next-step').textContent=step===2?t('Review your brief ↗','סקירת הפרטים ↖'):t('Continue ↗','ממשיכים ↖');$('#next-step').hidden=step===3;$('#form-error').textContent='';let html=`<h3 tabindex="-1">${title[step]}</h3>`;
if(step===0)html+=`<p class="form-hint">${t('Pick the direction that feels right.','בחרו את הכיוון שמתאים לכם.')}</p>${radios('type')}<label class="field">${t('Where are you now?','איפה אתם היום?')}<select name="stage">${choices.stage.map(c=>`<option value="${c[0]}" ${state.stage===c[0]?'selected':''}>${t(c[1],c[2])}</option>`).join('')}</select></label>`;
if(step===1)html+=`<p class="form-hint">${t('A few lines are enough to get started.','כמה שורות יספיקו כדי להתחיל.')}</p><label class="field">${t('The idea or challenge *','הרעיון או האתגר *')}<textarea name="idea" required minlength="10" maxlength="1500" placeholder="${t('What would you love to create, and who is it for?','מה תרצו ליצור, ולמי זה מיועד?')}">${escape(state.idea)}</textarea></label>${select('budget',t('An initial budget (ILS)','תקציב ראשוני (ש״ח)'))}${select('timeline',t('Ideal timing','מתי תרצו להתחיל?'))}`;
if(step===2)html+=`<p class="form-hint">${t('Just the essentials, so we can start a conversation.','רק הפרטים החשובים, כדי שנוכל להתחיל בשיחה.')}</p><label class="field">${t('Your name *','השם שלכם *')}<input name="name" autocomplete="name" required maxlength="100" value="${escape(state.name)}"></label><label class="field">${t('Email address *','כתובת אימייל *')}<input type="email" name="email" autocomplete="email" dir="ltr" required maxlength="150" value="${escape(state.email)}"></label><p class="privacy-note">${t('Your answers stay on this page until you choose Email or WhatsApp in the next step. Nothing is sent automatically.','התשובות נשארות בעמוד עד שתבחרו אימייל או וואטסאפ בשלב הבא. שום דבר לא נשלח אוטומטית.')}</p>`;
if(step===3)html+=`<p class="form-hint">${t('Review your brief, then choose how to reach us.','עברו על הפרטים ובחרו איך לפנות אלינו.')}</p><div class="review">${escape(brief())}</div><div class="send-options"><a class="pill dark" href="https://wa.me/972538203770?text=${encodeURIComponent(brief())}" target="_blank" rel="noopener noreferrer">WhatsApp ↗</a><a class="pill primary" href="mailto:770labs@gmail.com?subject=${encodeURIComponent(t('Let’s build something — ','בואו נבנה משהו — ')+state.name)}&body=${encodeURIComponent(brief())}">${t('Open email draft ↗','פתיחת טיוטת אימייל ↗')}</a></div><p class="privacy-note">${t('This opens a prepared message. Review it and press Send in your chosen app. Your enquiry has not been sent yet.','תיפתח הודעה מוכנה. בדקו אותה ולחצו על שליחה באפליקציה שבחרתם. הפנייה עדיין לא נשלחה.')}</p><button type="button" class="text-link" id="copy-brief" style="margin-top:15px">${t('Copy the brief instead','העתקת פרטי הפנייה')}</button><p id="copy-status" class="copied" role="status"></p>`;
$('#form-step').innerHTML=html;
$('#copy-brief')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(brief());$('#copy-status').textContent=t('Brief copied.','פרטי הפנייה הועתקו.')}catch{$('#copy-status').textContent=t('Select and copy the summary above.','סמנו והעתיקו את הסיכום למעלה.')}});
}
function saveStep(){new FormData(form).forEach((v,k)=>{if(k in state)state[k]=String(v).trim()})}
form.addEventListener('input',saveStep);form.addEventListener('change',saveStep);
form.addEventListener('submit',e=>{e.preventDefault();saveStep();if(step===0&&!state.type){$('#form-error').textContent=t('Choose a project type to continue.','בחרו סוג פרויקט כדי להמשיך.');return}if(step===1&&state.idea.trim().length<10){$('#form-error').textContent=t('Tell us a little more (at least 10 characters).','ספרו לנו קצת יותר (לפחות 10 תווים).');return}if(step===2&&!state.name.trim()){ $('#form-error').textContent=t('Please enter your name.','אנא הזינו שם.');return}if(step<3){step++;renderStep();$('#form-step h3').focus()}});
$('#back-step').addEventListener('click',()=>{saveStep();step=Math.max(0,step-1);renderStep();$('#form-step h3').focus()});
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
if('IntersectionObserver' in window&&!reduced.matches){document.body.classList.add('motion-ready');const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});$$('.reveal').forEach(el=>observer.observe(el))}
let ticking=false;function scrollUpdate(){const max=document.documentElement.scrollHeight-innerHeight;$('.scroll-progress').style.width=(max>0?scrollY/max*100:0)+'%';ticking=false}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(scrollUpdate);ticking=true}},{passive:true});scrollUpdate();
if(!reduced.matches&&matchMedia('(pointer:fine)').matches){$('.hero').addEventListener('pointermove',e=>{$('.hero-art').style.setProperty('--tilt',((e.clientX/innerWidth-.5)*4)+'deg')});$('.hero').addEventListener('pointerleave',()=>$('.hero-art').style.setProperty('--tilt','0deg'))}
$$('.services details').forEach(detail=>detail.addEventListener('toggle',()=>{if(detail.open)$$('.services details').forEach(other=>{if(other!==detail)other.open=false})}));
})();
